class Solution {
    public:long long numberOfPairs(vector<int>& nums1,vector<int>& nums2,int diff){
        int n=nums1.size();
        vector<int> values(n);
        for(int i=0;i<n;++i)values[i]=nums1[i]-nums2[i];
        vector<int> coordinates=values;
        sort(coordinates.begin(),coordinates.end());
        coordinates.erase(unique(coordinates.begin(),coordinates.end()),coordinates.end());
        vector<int> tree(coordinates.size()+1);
        long long answer=0;
        for(int value:values){
            int index=upper_bound(coordinates.begin(),coordinates.end(),value+diff)-coordinates.begin();
            for(int x=index;x;x-=x&-x)answer+=tree[x];
            index=lower_bound(coordinates.begin(),coordinates.end(),value)-coordinates.begin()+1;
            for(int x=index;x<(int)tree.size();x+=x&-x)++tree[x];
        }
        return answer;
    }
};
